build=r'''#!/usr/bin/env node
import crypto from'node:crypto';import fs from'node:fs';import path from'node:path';import{fileURLToPath}from'node:url';const R=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..'),read=p=>JSON.parse(fs.readFileSync(path.join(R,p),'utf8')),bytes=p=>fs.readFileSync(path.join(R,p)),J=(p,v)=>{let t=path.join(R,p);fs.mkdirSync(path.dirname(t),{recursive:true});fs.writeFileSync(t,JSON.stringify(v,null,2)+'\n')},W=(p,v)=>{let t=path.join(R,p);fs.mkdirSync(path.dirname(t),{recursive:true});fs.writeFileSync(t,v)},H=v=>crypto.createHash('sha256').update(v).digest('hex');
export const dimensions=['support_adjusted_surplus','cross_domain_transfer','exception_handling','custody','model_elasticity','governed_capacity','non_zero_sum_orientation','epistemic_restraint'];
export const scope=['.github/workflows/counter-selector-wave-08.yml','data/project/counter-selector-wave-08-blind-review.json','schemas/counter-selector-wave-08-blind-review.schema.json','docs/methods/counter-selector-wave-08-blind-review.md','docs/milestones/counter-selector-wave-08.md','tools/build-counter-selector-wave-08.mjs','tools/validate-counter-selector-wave-08.mjs','test/counter-selector-wave-08.test.js'];
export function manifest(){let e=scope.map(p=>{let x=bytes(p);return{path:p,sha256:H(x),bytes:x.length}});return{schema_version:'counter-selector-wave-08-release-manifest@1',program_id:'counter-selector-v1',wave_id:'CS-W08-B02',as_of:'2026-07-31',hash_mode:'sha256_exact_bytes',scope_ordered:true,self_included:false,entries:e,combined_sha256:H(e.map(x=>`${x.path}\0${x.sha256}\0${x.bytes}\n`).join('')),boundaries:{exact_bytes_prove_review_quality:false,manifest_proves_external_independence:false,manifest_proves_operator_capacity:false,manifest_authorizes_field_test:false,manifest_authorizes_ranking:false,manifest_authorizes_graph_edge:false,graph_effect:'none'}}}
export function registry(c,parent,parentManifest){let by=Object.fromEntries(parent.packets.map(x=>[x.packet_id,x]));let records=c.review_records.map(x=>{let p=by[x.packet_id];if(!p)throw Error(`missing parent packet ${x.packet_id}`);if(p.attribution_class!==x.expected_parent_attribution_class)throw Error(`attribution mismatch ${x.packet_id}`);return{schema_version:'counter-selector-blind-review-b02@1',program_id:c.program_id,wave_id:c.wave_id,packet_id:x.packet_id,parent_packet_sha256:H(JSON.stringify(p)),parent_attribution_class:p.attribution_class,review_passes:structuredClone(x.review_passes),dimension_vector:structuredClone(x.dimension_vector),bounded_support_count:x.bounded_support_count,mechanism_observations:structuredClone(x.mechanism_observations),disagreement:structuredClone(x.disagreement),disposition:x.disposition,analysis_class_recommendation:structuredClone(x.analysis_class_recommendation),field_test_eligible:false,operator_finding:false,promotion_generated:false,person_ranking_generated:false,public_identity_release_authorized:false,graph_effect:'none'}});return{schema_version:'counter-selector-blind-review-b02-registry@1',program_id:c.program_id,wave_id:c.wave_id,as_of:c.as_of,status:'four_internal_blind_reviews_complete_external_independence_not_claimed',parent_release_sha256:parentManifest.combined_sha256,counts:structuredClone(c.expected_counts),records,next_action:'Acquire support, handoff, transfer, and original-work receipts for the two bounded function packets. Retain the two system packets as mechanism controls. Do not launch a field test.',boundaries:structuredClone(c.boundaries)}}
export function ledger(c,r){return{schema_version:'counter-selector-review-disagreement-b02-ledger@1',program_id:c.program_id,wave_id:c.wave_id,as_of:c.as_of,status:'four_disagreements_preserved_not_averaged',counts:{disagreements:r.records.length,resolved_by_averaging:0,field_test_authorizations:0,graph_effects:0},records:r.records.map(x=>({packet_id:x.packet_id,question:x.disagreement.question,artifact_validity_position:x.disagreement.artifact_validity_position,adversarial_position:x.disagreement.adversarial_position,resolution:x.disagreement.resolution,changes_operator_finding:false,changes_field_test_eligibility:false,graph_effect:'none'})),boundaries:{disagreement_is_failure:false,averaging_authorized:false,disagreement_authorizes_field_test:false,graph_effect:'none'}}}
const E=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
export function report(c,r,l,m){return{schema_version:'counter-selector-wave-08-report@1',program_id:c.program_id,wave_id:c.wave_id,as_of:c.as_of,title:c.title,status:r.status,parent_release_sha256:r.parent_release_sha256,counts:r.counts,packet_results:r.records.map(x=>({packet_id:x.packet_id,parent_attribution_class:x.parent_attribution_class,bounded_support_count:x.bounded_support_count,dimension_vector:x.dimension_vector,mechanism_observations:x.mechanism_observations,disposition:x.disposition,analysis_class_recommendation:x.analysis_class_recommendation,field_test_eligible:false,operator_finding:false,graph_effect:'none'})),disagreement_ledger:{path:'data/project/counter-selector-review-disagreement-b02-ledger.json',count:l.records.length},next_action:r.next_action,boundaries:{...r.boundaries,...l.boundaries},release_manifest:{path:'data/project/counter-selector-wave-08-release-manifest.json',combined_sha256:m.combined_sha256}}}
export function html(r){let rows=r.packet_results.map(x=>`<tr><td><code>${E(x.packet_id)}</code></td><td>${E(x.parent_attribution_class)}</td><td>${x.bounded_support_count}</td><td>${E(x.disposition)}</td><td>${x.field_test_eligible}</td></tr>`).join('');return`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><title>Counter-Selector Wave 08</title><style>body{max-width:1320px;margin:auto;padding:42px 24px;font:16px/1.55 system-ui;background:#f1eee7;color:#171714}h1{font-size:4rem}.state{font-weight:900;color:#7b2e1d}table{width:100%;background:#fff;border-collapse:collapse}td,th{padding:10px;border:1px solid #ddd}.boundary{margin-top:25px;padding:18px;border-left:7px solid #7b2e1d;background:#fff;white-space:pre-wrap}</style></head><body><h1>Review without conversion</h1><p class="state">4 PACKETS · 8 PASSES · 4 BOUNDED SUPPORTS · 0 FIELD TESTS</p><table><thead><tr><th>Packet</th><th>Attribution</th><th>Supports</th><th>Disposition</th><th>Field test</th></tr></thead><tbody>${rows}</tbody></table><div class="boundary">procedural separation ≠ external independence\ncollective work ≠ individual operator\nsystem mechanism ≠ person or partnership\nbounded support ≠ field-test authority</div><p>${E(r.next_action)}</p><code>${r.release_manifest.combined_sha256}</code></body></html>\n`}
export function build(){let c=read('data/project/counter-selector-wave-08-blind-review.json'),p=read(c.parent_packet_registry_path),pm=read(c.parent_release_path),r=registry(c,p,pm),l=ledger(c,r);J('data/project/counter-selector-blind-review-b02-registry.json',r);J('data/project/counter-selector-review-disagreement-b02-ledger.json',l);let m=manifest();J('data/project/counter-selector-wave-08-release-manifest.json',m);let q=report(c,r,l,m);J('reports/core-thesis/counter-selector-wave-08/data.json',q);W('reports/core-thesis/counter-selector-wave-08/index.html',html(q));console.log('wave08',m.combined_sha256)}if(process.argv[1]===fileURLToPath(import.meta.url))build();
'''
W('tools/build-counter-selector-wave-08.mjs',build)
